def money(x):
    return f'${x:,.0f}'


def money_mcq(r, right, cands):
    """MCQ on money values: dedupe distractors, pad with nearby plausible slips."""
    seen, ds = {money(right)}, []
    pads = [round(right * f / 50) * 50 for f in (1.1, 0.9, 1.25, 0.75, 1.5, 2)]
    for c in list(cands) + pads:
        m = money(c)
        if c > 0 and m not in seen:
            seen.add(m)
            ds.append(m)
        if len(ds) == 3:
            break
    return mcq(r, money(right), ds)


