             law=['an advertisement of a reward can be a unilateral offer to the whole world (Carlill v Carbolic Smoke Ball Co)', 'acceptance is by performing the act, without notifying the offeror', 'the person performing must know of the offer to accept it (R v Clarke (1927), Australia)'],
