      ars=[('Damages in tort aim to put the claimant in the position as if the tort had not happened.', 'Compensatory damages restore the claimant so far as money can.', 'A'),
           ('Exemplary damages are awarded in most negligence cases.', 'Rookes v Barnard (1964) limited exemplary damages to narrow categories.', 'D')],
      exps=[('Explain the difference between pecuniary and non-pecuniary loss, with examples.', 'Pecuniary loss is financial and calculable, e.g. lost earnings, medical and care costs; non-pecuniary loss is non-financial, e.g. pain, suffering and loss of amenity (H West v Shephard).', '1 mark pecuniary + example; 1 mark non-pecuniary + example. [2]'),
            ('Explain the advantages and disadvantages of lump-sum damages.', 'Advantages: finality, the claimant can control the money; disadvantages: it is based on predictions about the future that may be wrong, may be spent too quickly or run out; periodical payments (Damages Act 1996) and provisional damages address this.', '1 mark advantage; 1 mark disadvantage; 1 mark alternative. [3]')],
      cmps=[('special damages', 'general damages', ['special damages are precisely calculated past pecuniary losses, general damages cover non-pecuniary and future losses assessed by the court'])],
