@t.add('C3', (1, 2, 3, 4, 5), 'numerical')
def award_calc(r, D):
    A = r.choice(PEOPLE)
    earn = r.choice([1500, 2000, 2500, 3200, 4000])
    months = r.choice([3, 4, 6, 8, 9, 12])
    med = r.choice([2500, 4000, 6500, 9000])
    psla = r.choice([12000, 18000, 25000, 40000])
    special = earn * months + med
    total = special + psla
    if D == 1:
        opts, ans = money_mcq(r, special, [earn * months, total, med + psla])
        return {'stem': f'{A} lost earnings of {money(earn)} a month for {months} months and paid {money(med)} in medical expenses before the trial. What are {A}\'s special damages?',
                'options': opts, 'answer': ans, 'key': f'Special damages = {money(earn)} × {months} + {money(med)} = {money(special)}.', 'marks': 1}
    stem = (f'{A} was injured by a negligent driver. Before trial {A} lost earnings of {money(earn)} a month for {months} months and paid medical expenses of {money(med)}. '
            f'The court assesses pain, suffering and loss of amenity at {money(psla)}.')
    key = f'Special damages = {money(earn)} × {months} + {money(med)} = {money(special)} [1]; general damages for PSLA = {money(psla)} [1]; total = {money(total)} [1]'
    mk, ans = 3, f'Special {money(special)}; general {money(psla)}; total {money(total)}.'
    if D >= 3:
        pct = r.choice([10, 20, 25])
        final = total * (100 - pct) // 100
        stem += f' {A} was found {pct}% contributorily negligent.'
        key += f'; reduced by {pct}% under the 1945 Act: {money(total)} × {100 - pct}% = {money(final)} [1]'
        mk, ans = 4, ans + f' After a {pct}% reduction: {money(final)}.'
    stem += ' Calculate the special damages, the general damages and the total award' + (' after the reduction.' if D >= 3 else '.')
    return {'stem': stem, 'answer': ans, 'key': key + f'. [{mk}]', 'type': 'numerical', 'marks': mk}


